INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES ("2021/11/18 14:59:59", 0.0, "ミッションをクリアして、\n報酬をゲットしましょう！", 10078, 10078002, 2, "2021/10/31 12:00:00", 190801, 1, 2, 3.099, 53, -416.5, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES ("2021/11/18 14:59:59", 0.0, "受け取ることができる\n報酬があるようです\n確認してみてください", 10078, 10078003, 3, "2021/10/31 12:00:00", 190801, 1, 2, 2.801, 54, -416.5, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES ("2021/11/18 14:59:59", 0.0, "報酬がもらえますよ！\nチェックしてみてください", 10078, 10078004, 4, "2021/10/31 12:00:00", 190801, 2, 2, 0.0, 54, -416.5, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES ("2021/11/18 14:59:59", 0.0, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", 10078, 10078005, 5, "2021/10/31 12:00:00", 190801, 1, 1, 0.0, 57, -416.5, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES ("2021/11/18 14:59:59", 0.0, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", 10078, 10078006, 1, "2021/10/31 12:00:00", 190801, 1, 2, 5.506, 55, -363.0, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES ("2021/11/18 14:59:59", 0.0, "お疲れ様です！\nここでは、討伐証と報酬を\n交換することができます！", 10078, 10078007, 2, "2021/10/31 12:00:00", 190801, 2, 1, 1.216, 55, -363.0, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES ("2021/11/18 14:59:59", 0.0, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", 10078, 10078008, 3, "2021/10/31 12:00:00", 190801, 2, 1, 1.539, 56, -363.0, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES ("2021/11/18 14:59:59", 0.0, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", 10078, 10078009, 4, "2021/10/31 12:00:00", 190801, 2, 1, 1.875, 56, -363.0, "カリン");
