INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES ("2022/02/24 14:59:59", 0.0, "ミッションをクリアして、\n報酬をゲットしましょう！", 10085, 10085002, 2, "2022/02/07 12:00:00", 190801, 1, 2, 3.099, 53, -416.5, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES ("2022/02/24 14:59:59", 0.0, "受け取ることができる\n報酬があるようです\n確認してみてください", 10085, 10085003, 3, "2022/02/07 12:00:00", 190801, 1, 2, 2.801, 54, -416.5, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES ("2022/02/24 14:59:59", 0.0, "報酬がもらえますよ！\nチェックしてみてください", 10085, 10085004, 4, "2022/02/07 12:00:00", 190801, 2, 2, 0.0, 54, -416.5, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES ("2022/02/24 14:59:59", 0.0, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", 10085, 10085005, 5, "2022/02/07 12:00:00", 190801, 1, 1, 0.0, 57, -416.5, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES ("2022/02/24 14:59:59", 0.0, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", 10085, 10085006, 1, "2022/02/07 12:00:00", 190801, 1, 2, 5.506, 55, -363.0, "カリン");
