INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES ("2022/02/24 14:59:59", 0.0, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", 10085, 10085008, 3, "2022/02/07 12:00:00", 190801, 2, 1, 1.539, 56, -363.0, "カリン");
